+function endDrag(e){if(!state.dragging)return;state.dragging=false;dragNote.classList.remove('on');const near=Math.abs(pirate.position.x)<.84&&pirate.position.y<1.6;if(near){resetCaptain()}else{state.anim='idle';pirate.position.x=0;pirate.rotation.z=0;setStatus('Almost got him!', 'Hold the captain and pull him lower, right over the barrel.', 'Aim for the round opening',false);thud();setTimeout(()=>{if(state.popped&&state.anim==='idle')setStatus('He is still out!', 'Drag the captain down into the barrel to tuck him in.', 'Aim for the opening',false)},1750)}}
 canvas.addEventListener('pointerup',endDrag);canvas.addEventListener('pointercancel',endDrag);
