 window.addEventListener('keydown',e=>{if(e.key>='1'&&e.key<='4')chooseBlade(swordButtons[Number(e.key)-1]);if((e.key===' '||e.key==='Enter')&&state.popped&&!state.dragging){pirate.position.x=0;pirate.position.y=.8;resetCaptain()}});
 document.querySelector('#sound-button').addEventListener('click',e=>{state.muted=!state.muted;e.currentTarget.textContent=state.muted?'♩':'♫';e.currentTarget.classList.toggle('sound-on',!state.muted);e.currentTarget.setAttribute('aria-label',state.muted?'Turn sound on':'Mute sound');if(!state.muted)clickSound()});

