 function pickPirate(event){if(!state.popped||state.anim!=='idle')return false;worldPointer(event);const objs=[];pirate.traverse(o=>{if(o.isMesh)objs.push(o)});raycaster.setFromCamera(pointer,camera);const hits=raycaster.intersectObjects(objs,false);return hits.length>0}
 canvas.addEventListener('pointerdown',e=>{if(!pickPirate(e))return;e.preventDefault();canvas.setPointerCapture(e.pointerId);state.dragging=true;state.anim='drag';worldPointer(e);state.dragOffsetY=pirate.position.y-intersection.y;dragNote.classList.add('on');title.textContent='Bring him home';copy.textContent='Lower the captain into the barrel opening';});
 canvas.addEventListener('pointermove',e=>{if(!state.dragging)return;e.preventDefault();worldPointer(e);pirate.position.y=THREE.MathUtils.clamp(intersection.y+state.dragOffsetY,.42,3.8);pirate.position.x=THREE.MathUtils.clamp(intersection.x,-2.8,2.8);pirate.position.z=.08;pirate.rotation.z=THREE.MathUtils.clamp((intersection.x)*-.09,-.22,.22)});
